    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1nw411h7u3', 'course-bili-bv1nw411h7u3', '100001', '0', 'BILI-LANG-005', 'course-category-language', 'instructor-bili-23693515', '韩语发音教学2017新版【合集】养乐多老师制作-韩语入门-自学韩语', '15 讲完整课程 · 6 小时 28 分钟', '养乐多老师2017新版韩语发音教学合集，视频制作不易，希望大家能帮忙多多扩散分享，现在是2023年的8月，跟着今年暑期和B站的活动，在这个合集里我也陆续更新了简版', '课程简介：养乐多老师2017新版韩语发音教学合集，视频制作不易，希望大家能帮忙多多扩散分享，现在是2023年的8月，跟着今年暑期和B站的活动，在这个合集里我也陆续更新了简版的音变教学。目前已更新了连音化和鼻音化的部分。原先也有出过完整版的音变，但那个难度较高，配合入门的话，这个简版的应该会更舒服一些 课程结构：共 2 章 15 讲，累计时长 6 小时 28 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/e33508e8e7a07491da9db3cbc4827fc520e665a9.jpg', '["语言学习","口语训练","考试备考","教程","韩语发音教学2017新版","合集"]', 23331, 15, 817766, '4.5', 254568, 'BV1NW411h7U3', NULL, NULL, NULL, 1, 0, 'standard', NULL, '韩语养乐多老师', 0, 'tenant', 'published', '2017-12-08T04:20:18.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
