    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1z4411c7jg', 'course-bili-bv1z4411c7jg', '100001', '0', 'BILI-LANG-006', 'course-category-language', 'instructor-bili-12359115', '英语语法从入门到高级 要恶补英语语法的快来吧', '23 讲完整课程 · 4 小时 2 分钟', '写在最前面，这个语法系列完全是，我4年前自己做的一个“费曼学习法”的理论实践，起初只是为了讲给自己听，后面才分享出来给大家，一起进步一起学习，我并没有预料到会有那么多人看，我并不是一个专业的英文老师，我只是一个自学英语出', '课程简介：写在最前面，这个语法系列完全是，我4年前自己做的一个“费曼学习法”的理论实践，起初只是为了讲给自己听，后面才分享出来给大家，一起进步一起学习，我并没有预料到会有那么多人看，我并不是一个专业的英文老师，我只是一个自学英语出国的普通人。如果你认为我讲的东西，没有价值学不到东西，你可以选择不看这个视频，去看更适合你的视频。我自己开发了一个适合初学者的学习网站，到音标发音，到基本词汇，到全部语法内容，到实用日常对话。最后喜欢大家都能学好外语，利用好语言这个杠杆。课程结构：共 3 章 23 讲，累计时长 4 小时 2 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/5e0fe2955088202a75f90acc3f5f5260a3785d90.jpg', '["语言学习","口语训练","考试备考","英语语法自学","英语语法从入门到高级","要恶补英语语法的快来吧"]', 14560, 23, 3631952, '4.7', 1158701, 'BV1Z4411C7jG', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'JackyangMiao', 0, 'tenant', 'published', '2019-09-04T14:45:20.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
