    ('course-bili-bv1dv4y177uk', 'course-bili-bv1dv4y177uk', '100001', '0', 'BILI-LANG-009', 'course-category-language', 'instructor-bili-1599722755', '暑假别浪费！B站最好学的韩语入门教程，0基础到TOPIK6，每天只需10分钟！', '70 讲完整课程 · 10 小时 14 分钟', '暑假别浪费！B站最好学的韩语入门教程，0基础到TOPIK6，每天只需10分钟！。共 70 讲，累计 10.2 小时，由 Candy韩语 讲解，章节结构完整，可直接在课程播放器中观看。', '课程简介：喜欢请三连支持一下鸭！还会更新更多韩语教程~ 课程结构：共 9 章 70 讲，累计时长 10 小时 14 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/a84e03dfd0cc99af61f9fe4136a1b20282a14015.png', '["语言学习","口语训练","考试备考","韩语1000集","0基础到TOPIK6","每天只需10分钟！"]', 36857, 70, 125229, '4.6', 31201, 'BV1DV4y177Uk', '79.00', '126.40', 'CNY', 0, 0, 'standard', NULL, 'Candy韩语', 0, 'tenant', 'published', '2022-07-25T12:24:02.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
