    ('course-bili-bv1fqfnyle3c', 'course-bili-bv1fqfnyle3c', '100001', '0', 'BILI-LANG-013', 'course-category-language', 'instructor-bili-3546830335904156', '清华大学190小时讲完雅思教程，从零基础入门到精通全教程，全程无废话，这还学不会，我退出雅思界！！', '100 讲完整课程 · 18 小时 46 分钟', 'YouTube 想要学习雅思的小伙伴可以多看看这种动画形式的情景对话，不仅可以积累词汇量，还能让学习变得没那么困难，帮助大家在轻松愉悦的情况下积累词汇练习口语。', '课程简介：YouTube 想要学习雅思的小伙伴可以多看看这种动画形式的情景对话，不仅可以积累词汇量，还能让学习变得没那么困难，帮助大家在轻松愉悦的情况下积累词汇练习口语。课程结构：共 13 章 100 讲，累计时长 18 小时 46 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/572aca753180a3a24865bad321735833e535961e.png', '["语言学习","口语训练","考试备考","从零基础入门到精通全教程","全程无废话","这还学不会"]', 67618, 100, 111379, '4.5', 50803, 'BV1FqfnYLE3C', '79.00', '126.40', 'CNY', 0, 0, 'standard', NULL, '萝卜上岸啦', 0, 'tenant', 'published', '2025-01-24T10:11:44.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
