    ('course-bili-bv1n64y1j79q', 'course-bili-bv1n64y1j79q', '100001', '0', 'BILI-LANG-022', 'course-category-language', 'instructor-bili-3546588389575164', '雅思6分全科精讲班（含讲义）IELTS 雅思基础', '56 讲完整课程 · 47 小时 36 分钟', '沈恩臻 发布的《雅思6分全科精讲班（含讲义）IELTS 雅思基础》，共 56 讲，总时长 47 小时 36 分钟。', '课程简介：《雅思6分全科精讲班（含讲义）IELTS 雅思基础》由 沈恩臻 发布，完整收录 56 讲内容。课程结构：共 7 章 56 讲，累计时长 47 小时 36 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/ecea6764840f481cc80f7fe6a957f5f5b21fde5b.jpg', '["语言学习","口语训练","考试备考","雅思6分全科精讲班","含讲义","IELTS"]', 171380, 56, 968, '4.4', 471, 'BV1N64y1j79Q', NULL, NULL, NULL, 1, 0, 'standard', NULL, '沈恩臻', 0, 'tenant', 'published', '2023-12-04T05:12:36.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
