VALUES
    ('course-bili-season-4014355', 'course-bili-season-4014355', '100001', '0', 'BILI-LANG-023', 'course-category-language', 'instructor-bili-15908963', '人教社新版日语七年级', '58 讲完整课程 · 23 小时 46 分钟', '新版人教七年级日语课程持续更新中 新的教材重新开始 欢迎各位老师们、同学们多多留言,', '课程简介：新版人教七年级日语课程持续更新中 新的教材重新开始 欢迎各位老师们、同学们多多留言,共同进步. 课程结构：共 1 章 58 讲，累计时长 23 小时 46 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/5ee9af455dd1fad7dc80c8222edde2fcede42f11.jpg', '["语言学习","口语训练","考试备考","人教社新版日语七年级"]', 85589, 58, 16455, '4.4', 1880, 'BV1XUm5YpE5e', '129.00', '206.40', 'CNY', 0, 0, 'standard', NULL, '日语老师孙缓缓', 0, 'tenant', 'published', '2024-10-14T08:40:01.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
