    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1dzm8yaeqj', 'course-bili-bv1dzm8yaeqj', '100001', '0', 'BILI-LANG-024', 'course-category-language', 'instructor-bili-36885818', '延世韩国语第一册精讲 (带课件)+活用练习册+延世阅读+口语练习【输入和输出结合，完成韩语学习闭环】【从头系统学韩语】', '34 讲完整课程 · 7 小时 46 分钟', '我是韩语私教那笙，在线韩语老师。本课程为【延世韩国语】教材配套的精讲视频，是我真的用心做的课件录制的视频,希望帮助到刚入门决心开始系统学习韩语的同学。如果是自学韩语的同学，可以跟着视频的顺序：单词 ->', '课程简介：我是韩语私教那笙，在线韩语老师。本课程为【延世韩国语】教材配套的精讲视频，是我真的用心做的课件录制的视频,希望帮助到刚入门决心开始系统学习韩语的同学。如果是自学韩语的同学，可以跟着视频的顺序：单词 -> 语法 -> 课文 -> 课后练习 -> 口语练习 的顺序学习每课内容～（我也发布了18天零基础韩语发音课的完整发音课程） 如果是想以后考TOPIK的同学，推荐配合延世活用练习册和延世阅读一起自学，刚开始就把基础打好。课程结构：共 5 章 34 讲，累计时长 7 小时 46 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'intermediate', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/52b6deb14f6f8cda37ab80167050cf987dc1e9f7.jpg', '["语言学习","口语训练","考试备考","延世韩国语第一册精讲","带课件","活用练习册"]', 27977, 34, 12766, '4.4', 2393, 'BV1DZm8YaEqJ', NULL, NULL, NULL, 1, 0, 'standard', NULL, '韩语私教那笙', 0, 'tenant', 'published', '2024-11-12T08:03:42.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
